package com.example.starter.ili;

/**
 * 缺陷深度增长率分级口径：
 * 增长率 &lt; 5%/年为稳定；&ge; 5%/年为增长；&ge; 15%/年为严重。
 */
public enum Grade {
    /** 稳定：年增长率小于 5%。 */
    STABLE,
    /** 增长：年增长率达到或超过 5%，且小于 15%。 */
    GROWING,
    /** 严重：年增长率达到或超过 15%。 */
    SEVERE;

    /**
     * 按年增长率（壁厚百分比/年）判定分级。
     */
    public static Grade of(double growthRatePerYear) {
        if (growthRatePerYear >= 15.0) {
            return SEVERE;
        }
        if (growthRatePerYear >= 5.0) {
            return GROWING;
        }
        return STABLE;
    }
}

package com.example.starter.ili;

/**
 * 对齐批次状态。SEALED 为终态：封板后任何修改与迟到复核均被拒绝。
 */
public enum BatchStatus {
    /** 开放：可提交复核结论。 */
    OPEN,
    /** 已封板：终态，重复封板幂等成功。 */
    SEALED
}

package com.example.starter.ili;

/**
 * 缺陷读数的对齐去向。
 */
public enum MatchOutcome {
    /** 已与另一回合读数配对。 */
    MATCHED,
    /** 仅出现在新回合：新发现缺陷。 */
    NEW_FOUND,
    /** 仅出现在旧回合：已消失缺陷。 */
    DISAPPEARED
}

package com.example.starter.ili;

/**
 * 匹配对复核状态。仅增长、严重缺陷需要复核。
 */
public enum ReviewStatus {
    /** 稳定缺陷，无需复核。 */
    NOT_REQUIRED,
    /** 待复核。 */
    PENDING,
    /** 复核确认原分级。 */
    CONFIRMED,
    /** 复核降级到较低等级。 */
    DOWNGRADED
}

