package com.example.starter.ili;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 对齐批次视图：批次元信息、匹配对清单与未匹配读数清单。
 */
public record BatchView(
        long batchId,
        String requestId,
        String segmentId,
        String oldRunId,
        String newRunId,
        LocalDate oldRunDate,
        LocalDate newRunDate,
        BatchStatus status,
        LocalDateTime createdAt,
        LocalDateTime sealedAt,
        List<MatchView> matches,
        List<ReadingView> unmatchedReadings) {

    /**
     * 缺陷匹配对视图。
     */
    public record MatchView(
            long matchId,
            String oldDefectRef,
            String newDefectRef,
            BigDecimal oldMileageM,
            BigDecimal newMileageM,
            BigDecimal mileageDiffM,
            BigDecimal oldDepthPct,
            BigDecimal newDepthPct,
            BigDecimal growthRate,
            Grade grade,
            ReviewStatus reviewStatus,
            Grade finalGrade,
            String reviewedBy,
            LocalDateTime reviewedAt) {
    }

    /**
     * 未匹配读数视图（新发现或已消失）。
     */
    public record ReadingView(
            String runSide,
            String defectRef,
            BigDecimal mileageM,
            BigDecimal depthPct,
            MatchOutcome outcome) {
    }
}

package com.example.starter.ili;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码，由全局异常处理器转换为错误响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    /**
     * 404：资源不存在。
     */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }

    /**
     * 409：幂等冲突或状态冲突（如封板后修改）。
     */
    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    /**
     * 422：业务规则不满足（如降级目标不合法）。
     */
    public static ApiException unprocessable(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }
}

